#define main original_hecbench_main
#include "native_corrected/main.cu"
#undef main
#include <type_traits>
#include <cmath>
template<class T>int study(const char*mode){constexpr int n=100000,pad=1024,repeats=10;std::string base="/home/imo/HeCBench_julia/src/merge-julia/";std::vector<T>input(2*(n+pad)),cpu(2*n),out(2*n+pad);std::vector<unsigned>hp(226),expected_path(226);auto read=[&](const std::string&name,void*ptr,size_t bytes){FILE*f=fopen((base+name).c_str(),"rb");if(!f||fread(ptr,1,bytes,f)!=bytes)exit(5);fclose(f);};read(std::string("study_input_")+mode+".bin",input.data(),input.size()*sizeof(T));read(std::string("study_expected_")+mode+".bin",cpu.data(),cpu.size()*sizeof(T));read(std::string("study_paths_")+mode+".bin",expected_path.data(),226*4);std::vector<T>expected=input;expected.insert(expected.end(),cpu.begin(),cpu.end());for(auto v:expected_path)expected.push_back(T(v));T *a,*b,*c;unsigned*dpi;cudaMalloc(&a,(n+pad)*sizeof(T));cudaMalloc(&b,(n+pad)*sizeof(T));cudaMalloc(&c,out.size()*sizeof(T));cudaMalloc(&dpi,226*4);cudaMemcpy(a,input.data(),(n+pad)*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(b,input.data()+n+pad,(n+pad)*sizeof(T),cudaMemcpyHostToDevice);auto launch=[&](){workloadDiagonals<T><<<112,32>>>(a,n,b,n,dpi);mergeSinglePath<T,false,false><<<112,128>>>(a,n,b,n,dpi,c,2*n);cudaDeviceSynchronize();};launch();if(cudaGetLastError()!=cudaSuccess)return 4;bool allok=true;for(int trial=1;trial<=5;trial++){cudaMemset(c,0,out.size()*sizeof(T));cudaMemset(dpi,0,226*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeats;rep++)launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeats;cudaMemcpy(out.data(),c,out.size()*sizeof(T),cudaMemcpyDeviceToHost);cudaMemcpy(hp.data(),dpi,226*4,cudaMemcpyDeviceToHost);std::vector<T>got=input;got.insert(got.end(),out.begin(),out.begin()+2*n);for(auto v:hp)got.push_back(T(v));bool ok=status==cudaSuccess;double maxabs=0,maxrel=0;for(size_t i=0;i<got.size();i++){long double delta=fabsl((long double)got[i]-(long double)expected[i]);ok&=got[i]==expected[i]&&std::isfinite((long double)got[i]);maxabs=fmax(maxabs,double(delta));maxrel=fmax(maxrel,double(delta/fmaxl(fabsl((long double)expected[i]),1e-300L)));}allok&=ok;char filename[80];snprintf(filename,sizeof(filename),"output_trial%d.bin",trial);FILE*f=fopen(filename,"wb");if(!f)return 5;fwrite(got.data(),sizeof(T),got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"%s\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),maxabs,maxrel,filename,mode,got.size());}return allok?0:1;}
int main(int argc,char**argv){if(argc!=2)return 2;std::string mode=argv[1];if(mode=="uint32")return study<uint32_t>(argv[1]);if(mode=="uint64")return study<uint64_t>(argv[1]);if(mode=="float32")return study<float>(argv[1]);if(mode=="float64")return study<double>(argv[1]);return 3;}
